style.css:
@-moz-document domain("google.com"), domain("www.google.com") {
/* --- fallback tokens (used if you forget to set an image) --- */
  :root {
    --fallback-default: auto;
    --fallback-pointer: pointer;
    --fallback-text: text;
  }

  /* Replaceable placeholders (these are replaced by the Create Style settings).
     In Settings create image fields with install keys exactly:
       default_cursor    (for general cursor)
       pointer_cursor    (for links/buttons)
       ibeam_cursor      (for inputs/text)
     The value you pick/upload should be the full CSS value inserted, e.g.
       url(data:image/png;base64,...) 8 8, auto
     Or for .cur: url("https://.../mycursor.cur"), auto
  */

  /* ===== DEFAULT CURSOR (everywhere) ===== */
  html, body, * {
    cursor: /*[[default_cursor]]*/ var(--fallback-default) !important;
  }

  /* ===== POINTER CURSOR (links/buttons) ===== */
  a, button, [role="button"], [type="button"], [type="submit"],
  [jscontroller][jsaction*="click"], input[type="button"], input[type="submit"] {
    cursor: /*[[pointer_cursor]]*/ var(--fallback-pointer) !important;
  }

  /* ===== TEXT CURSOR (inputs, textareas, editable fields) ===== */
  input[type="text"], input[type="search"], input[type="email"], input[type="password"],
  input:not([type]), textarea, [contenteditable=""], [contenteditable="true"] {
    cursor: /*[[ibeam_cursor]]*/ var(--fallback-text) !important;
  }
}
